    switch (this.example) {
      case 'anchoring':
        rows = this.rows.map((row) => ({
          ...row,
          anchor: row.own === (this.anchorRole === 'user'),
        }));
        emptyTitle = 'Choose a turn boundary';
        emptyDescription = 'Send the first message to see the selected role anchor.';
