        </div>`;
        break;
      case 'group-chat':
        rows = [
          ...groupRows,
          ...(this.groupStep >= 1
            ? [
                {
                  id: 'alex-joined',
                  text: 'Alex joined the review',
                  own: false,
                  marker: true,
                  anchor: true,
                },
              ]
            : []),
          ...(this.groupStep >= 2
            ? [
                {
                  id: 'alex-reply',
                  text: 'I’ll handle the keyboard review. I can test the invitation flow this afternoon and post the findings before the pilot begins.',
                  own: false,
                  author: 'Alex',
                  tinted: true,
                  anchor: false,
