            >${this.groupStep === 0 ? 'Add Alex' : 'Send as Alex'}</tp-button
          ><output
            >${this.groupStep === 0 ? 'The join marker starts the new turn.' : 'Alex’s reply belongs below the join marker.'}</output
          >
        </div>`;
